package net.officefloor.hq.app.person;


/**
 * A person on a sheet: a name and a dated grade (A, B or C): each grade they are given is in force
 * from its from-date, the first from the beginning of time (see {@link #gradeOn}). The name is kept without the spaces around
 * it and is unique on the sheet without regard to case, compared through its {@link #keyOf key}.
 */
@Entity
@Table(name = "person")
public class Person {

    @Id
    @GeneratedValue(strategy = GenerationType.IDENTITY)
    private Long id;

    @Column(name = "sheet_id", nullable = false)
    private String sheetId;

    @Column(name = "name", nullable = false)
    private String name;

    @Column(name = "name_key", nullable = false)
    private String nameKey;

    /** The grades the person has been given, at most one per from-date. */
    @ElementCollection(fetch = FetchType.EAGER)
    @CollectionTable(name = "person_grade", joinColumns = @JoinColumn(name = "person_id"))
    private List<PersonGrade> grades = new ArrayList<>();

    /** The date the person is retired from; null while they are not retired. */
    @Column(name = "retired_from")
    private LocalDate retiredFrom;

    /** The holds the person has been put on: their OPEN and PENDING claims dated within one count in no
     * live total, unless a statement binds them. The same hold may be put on more than once. Loaded by
     * a sub-select, so it loads eagerly beside the grades. */
    @ElementCollection(fetch = FetchType.EAGER)
    @Fetch(FetchMode.SUBSELECT)
    @CollectionTable(name = "person_hold", joinColumns = @JoinColumn(name = "person_id"))
    private List<PersonHold> holds = new ArrayList<>();

    /** The person's own terms in days, in place of their grade's and the sheet's; null when they have none. */
    @Column(name = "terms")
    private Integer terms;

    /** Raised each time the person is saved. */
    @Version
    @Column(name = "version", nullable = false)
    private long version;

    protected Person() {
    }

    public Person(String sheetId, String name, String grade) {
        this.sheetId = sheetId;
        setName(name);
        this.grades.add(new PersonGrade(grade, null));
    }

    /** The form of a name that is unique on a sheet: without surrounding spaces, in lower case. */
    public static String keyOf(String name) {
        return name.trim().toLowerCase(Locale.ROOT);
    }

    public Long getId() {
        return id;
    }

    public String getSheetId() {
        return sheetId;
    }

    public String getName() {
        return name;
    }

    public void setName(String name) {
        this.name = name.trim();
        this.nameKey = keyOf(name);
    }

    /** The grades the person has been given, by from-date (the one with none first). */
    public List<PersonGrade> getGrades() {
        return grades.stream()
                .sorted(Comparator.comparing(PersonGrade::getFrom, Comparator.nullsFirst(Comparator.naturalOrder())))
                .toList();
    }

    /** Gives the person {@code grade} from {@code from}, in place of one given from the same date. */
    public void setGrade(String grade, LocalDate from) {
        grades.removeIf(g -> from.equals(g.getFrom()));
        grades.add(new PersonGrade(grade, from));
    }

    /** The grade in force on {@code date}: the one with the latest from-date on or before it, or the
     * first one given when none has; the latest given when {@code date} is null. */
    public String gradeOn(LocalDate date) {
        PersonGrade best = null;
        for (PersonGrade g : getGrades()) {
            if (date != null && g.getFrom() != null && g.getFrom().isAfter(date)) continue;
            best = g;
        }
        return best == null ? null : best.getGrade();
    }

    public Integer getTerms() {
        return terms;
    }

    public void setTerms(Integer terms) {
        this.terms = terms;
    }

    public LocalDate getRetiredFrom() {
        return retiredFrom;
    }

    public void setRetiredFrom(LocalDate retiredFrom) {
        this.retiredFrom = retiredFrom;
    }

    /** Retired as soon as a retirement date is set, whatever the date. */
    public boolean isRetired() {
        return retiredFrom != null;
    }

    /** Whether the person's retirement date is reached on {@code today}: on or after it. */
    public boolean isRetiredOn(LocalDate today) {
        return retiredFrom != null && today != null && !today.isBefore(retiredFrom);
    }

    /** The holds the person has been put on, by from-date. */
    public List<PersonHold> getHolds() {
        return holds.stream()
                .sorted(Comparator.comparing(PersonHold::getFrom)
                        .thenComparing(PersonHold::getTo, Comparator.nullsLast(Comparator.naturalOrder())))
                .toList();
    }

    /** Puts the person on {@code hold}. */
    public void addHold(PersonHold hold) {
        holds.add(hold);
    }

    /** Whether the person has any hold, whatever its dates. */
    public boolean isHeld() {
        return !holds.isEmpty();
    }

    /** Whether {@code date} falls within any of the person's holds. */
    public boolean isHeldOn(LocalDate date) {
        return holds.stream().anyMatch(h -> h.covers(date));
    }

    /** Refuses a claim dated {@code date} when it falls after the person's retirement date. */
    public void requireClaimable(LocalDate date) {
        if (retiredFrom != null && date.isAfter(retiredFrom)) {
            throw new PersonRetiredException();
        }
    }

    public long getVersion() {
        return version;
    }
}
package net.officefloor.hq.app.person;


/** A hold a person was put on, from {@code from} to {@code to} (both included); a null to-date has no end. */
@Embeddable
public class PersonHold {

    @Column(name = "hold_from", nullable = false)
    private LocalDate from;

    @Column(name = "hold_to")
    private LocalDate to;

    protected PersonHold() {
    }

    public PersonHold(LocalDate from, LocalDate to) {
        this.from = from;
        this.to = to;
    }

    public LocalDate getFrom() {
        return from;
    }

    public LocalDate getTo() {
        return to;
    }

    /** Whether {@code date} falls within the hold. */
    public boolean covers(LocalDate date) {
        return date != null && !date.isBefore(from) && (to == null || !date.isAfter(to));
    }

    @Override
    public boolean equals(Object o) {
        return o instanceof PersonHold other && Objects.equals(from, other.from) && Objects.equals(to, other.to);
    }

    @Override
    public int hashCode() {
        return Objects.hash(from, to);
    }
}
package net.officefloor.hq.app.period;


/** A sheet's period: a name, unique on the sheet without regard to case, and the dates it runs from
 * and to, both inclusive. A claim belongs to the period whose dates contain its date. Once closed, its
 * due-total, and each person's due-total for it, are the ones fixed when it was closed, until it is
 * reopened. A soft-closed period is closed and its figures fixed the same way, but claims dated in it can
 * still change. */
@Entity
@Table(name = "period")
public class Period {

    @Id
    @GeneratedValue(strategy = GenerationType.IDENTITY)
    private Long id;

    @Column(name = "sheet_id", nullable = false)
    private String sheetId;

    @Column(name = "name", nullable = false)
    private String name;

    @Column(name = "name_key", nullable = false)
    private String nameKey;

    @Column(name = "from_date", nullable = false)
    private LocalDate from;

    @Column(name = "to_date", nullable = false)
    private LocalDate to;

    @Column(name = "closed", nullable = false)
    private boolean closed;

    /** Whether the period, while closed, is only soft-closed. */
    @Column(name = "soft", nullable = false)
    private boolean soft;

    /** The due-total fixed when the period was closed; null while it is open. */
    @Column(name = "closed_total", precision = 12, scale = 2)
    private BigDecimal closedTotal;

    /** Each person's due-total for the period fixed when it was closed, by person id; empty while it
     * is open. */
    @ElementCollection(fetch = FetchType.EAGER)
    @CollectionTable(name = "period_person_total", joinColumns = @JoinColumn(name = "period_id"))
    @MapKeyColumn(name = "person_id")
    @Column(name = "total", precision = 12, scale = 2, nullable = false)
    private Map<Long, BigDecimal> closedPersonTotals = new HashMap<>();

    protected Period() {
    }

    public Period(String sheetId, String name, LocalDate from, LocalDate to) {
        this.sheetId = sheetId;
        this.name = name.trim();
        this.nameKey = keyOf(name);
        this.from = from;
        this.to = to;
    }

    /** The name as compared: without the spaces around it, in lower case. */
    public static String keyOf(String name) {
        return name.trim().toLowerCase(Locale.ROOT);
    }

    public Long getId() {
        return id;
    }

    public String getSheetId() {
        return sheetId;
    }

    public String getName() {
        return name;
    }

    public LocalDate getFrom() {
        return from;
    }

    public LocalDate getTo() {
        return to;
    }

    public boolean isClosed() {
        return closed;
    }

    public boolean isSoft() {
        return soft;
    }

    public BigDecimal getClosedTotal() {
        return closedTotal;
    }

    public Map<Long, BigDecimal> getClosedPersonTotals() {
        return Map.copyOf(closedPersonTotals);
    }

    /** Close the period, fixing each person's due-total for it at {@code personTotals}, by person id,
     * and its own due-total at their sum. */
    public void close(Map<Long, BigDecimal> personTotals) {
        close(personTotals, false);
    }

    /** Close the period as {@link #close(Map)} does, soft-closed when {@code soft}. */
    public void close(Map<Long, BigDecimal> personTotals, boolean soft) {
        this.closed = true;
        this.soft = soft;
        this.closedPersonTotals.clear();
        this.closedPersonTotals.putAll(personTotals);
        this.closedTotal = personTotals.values().stream().reduce(BigDecimal.ZERO.setScale(2), BigDecimal::add);
    }

    /** Reopen the period: its due-total is live again. */
    public void reopen() {
        this.closed = false;
        this.soft = false;
        this.closedTotal = null;
        this.closedPersonTotals.clear();
    }

    /** Whether this period shares a day with the dates {@code from} to {@code to}, both inclusive. */
    public boolean overlaps(LocalDate from, LocalDate to) {
        return !this.from.isAfter(to) && !from.isAfter(this.to);
    }
}
package net.officefloor.hq.app.statement;


/** A statement taken of a person: the sheet's today when it was taken, the person's due-total then
 * (two decimals; null when it was n/a) and how many of their claims counted toward it. */
@Entity
@Table(name = "statement")
public class Statement {

    @Id
    @GeneratedValue(strategy = GenerationType.IDENTITY)
    private Long id;

    @Column(name = "sheet_id", nullable = false)
    private String sheetId;

    @Column(name = "person_id", nullable = false)
    private Long personId;

    @Column(name = "statement_date", nullable = false)
    private LocalDate date;

    @Column(name = "due_total", precision = 14, scale = 2)
    private BigDecimal dueTotal;

    @Column(name = "claim_count", nullable = false)
    private int claimCount;

    protected Statement() {
    }

    public Statement(String sheetId, Long personId, LocalDate date, BigDecimal dueTotal, int claimCount) {
        this.sheetId = sheetId;
        this.personId = personId;
        this.date = date;
        this.dueTotal = dueTotal;
        this.claimCount = claimCount;
    }

    public Long getId() {
        return id;
    }

    public String getSheetId() {
        return sheetId;
    }

    public Long getPersonId() {
        return personId;
    }

    public LocalDate getDate() {
        return date;
    }

    public BigDecimal getDueTotal() {
        return dueTotal;
    }

    public int getClaimCount() {
        return claimCount;
    }
}

